use axum::{
    middleware,
    response::IntoResponse,
    routing::{get, post, put},
    Router,
};
use tower::ServiceBuilder;
use tower_http::{
    cors::CorsLayer,
    compression::CompressionLayer,
    timeout::TimeoutLayer,
    trace::TraceLayer,
};
use std::time::Duration;

pub mod api;
pub mod config;
pub mod error;

pub use error::{AppError, AppResult};

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppConfig {
    pub port: u16,
    pub host: String,
    pub cors_origins: Vec<String>,
    pub request_timeout_seconds: u64,
    pub hardware: HardwareConfig,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct HardwareConfig {
    pub enable_gpio: bool,
    pub temperature_sensor_pin: Option<u8>,
    pub fan_control_pin: Option<u8>,
}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            port: 3000,
            host: "0.0.0.0".to_string(),
            cors_origins: vec!["*".to_string()],
            request_timeout_seconds: 30,
            hardware: HardwareConfig {
                enable_gpio: false,
                temperature_sensor_pin: None,
                fan_control_pin: None,
            },
        }
    }
}

use axum::Router;
use clap::Parser;
use rpi_smoker_backend::{api::routes::create_router, config::AppConfig};
use std::net::SocketAddr;
use tokio::signal;
use tracing::{info, warn};

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    /// Port to bind the server to
    #[arg(short, long, default_value = "3000")]
    port: u16,

    /// Host to bind the server to
    #[arg(long, default_value = "0.0.0.0")]
    host: String,

    /// Enable hardware features (GPIO, sensors)
    #[arg(long)]
    enable_hardware: bool,
}

fn create_app_config(args: &Args) -> AppConfig {
    let mut config = AppConfig::default();
    config.port = args.port;
    config.host = args.host.clone();
    config.hardware.enable_gpio = args.enable_hardware;
    config
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize tracing
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "rpi_smoker_backend=debug,tower_http=debug".into()),
        )
        .init();

    let args = Args::parse();
    let config = create_app_config(&args);

    // Check if we're on a Raspberry Pi or hardware features are enabled
    if config.hardware.enable_gpio {
        #[cfg(all(feature = "rpi-hardware", target_os = "linux"))]
        {
            info!("Hardware features enabled");
            // TODO: Initialize GPIO and sensor interfaces
        }
        #[cfg(not(all(feature = "rpi-hardware", target_os = "linux")))]
        {
            warn!("Hardware features requested but not available on this platform or not compiled in.");
            warn!("To enable hardware features: use --features rpi-hardware on Linux");
        }
    } else {
        info!("Running in development mode without hardware features");
    }

    let app = create_router();

    let addr = SocketAddr::from(([0, 0, 0, 0], config.port));
    info!("Starting server on {}:{}", config.host, config.port);
    info!("Health check available at http://{}:{}/api/health", config.host, config.port);
    info!("API routes available under /api/*");

    let listener = tokio::net::TcpListener::bind(addr).await?;

    // Run server with graceful shutdown
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    Ok(())
}

/// Handle graceful shutdown signals
async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        signal::unix::signal(signal::unix::SignalKind::terminate())
            .expect("failed to install signal handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("Received Ctrl+C, starting graceful shutdown");
        },
        _ = terminate => {
            info!("Received SIGTERM, starting graceful shutdown");
        },
    }
}

